insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('d29af820-f0d2-4519-a51c-dd2df2123769', 'N2', 'Vた／Aな／Aい ＋ ことに', 'Thật là.../Thật...làm sao/Biết bao khi... (mở đầu câu bằng cảm xúc của người nói)', NULL, 'Vた／Aな／Aい ＋ ことに', 'Đặt trước câu để nêu cảm xúc (vui/buồn/tiếc/phiền...) của người nói về sự việc sắp kể', NULL, NULL, NULL, '{}', NULL, 65, 'Vた／Aな／Aい ＋ ことに', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('fcbcd923-35a1-44e9-b7e0-c47640e43c4c', 'N2', '普通形（Aな／Aである／Nである） ＋ ことから', 'Vì là có việc.../Bởi... (nêu căn cứ/lý do dẫn đến kết luận)', NULL, '普通形（Aな／Aである／Nである） ＋ ことから', 'Nêu 1 sự việc/lý do làm căn cứ để dẫn đến 1 kết luận/quyết định/tên gọi', NULL, NULL, NULL, '{}', NULL, 65, '普通形（Aな／Aである／Nである） ＋ ことから', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('3b4f8ff8-1184-4d94-a0f8-76e866fc3d38', 'N2', 'N の ＋ ことだから', 'Vì là...nên chắc chắn (suy đoán dựa trên tính cách/thói quen đã biết của ai đó)', NULL, 'N の ＋ ことだから', 'Suy đoán về hành động của 1 người cụ thể dựa trên tính cách/thói quen thường thấy của người đó', NULL, NULL, NULL, '{}', NULL, 65, 'N の ＋ ことだから', 'pdf', 'ok')
