insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('fc69ea16-25fd-4255-a59a-d28a94132cba', 'N2', 'Vる ＋ ことはない', 'Không cần phải~ (an ủi/khuyên không cần thiết phải làm gì)', NULL, 'Vる ＋ ことはない', 'Trấn an/khuyên đối phương rằng không cần thiết phải làm 1 việc gì đó', NULL, NULL, NULL, '{}', NULL, 65, 'Vる ＋ ことはない', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('995943ee-3c92-40c0-8db3-119e36b765f6', 'N2', 'Vる／Vない ＋ こと', 'Hãy, phải.../Không được... (mệnh lệnh/quy định gián tiếp bằng văn bản)', NULL, 'Vる／Vない ＋ こと', 'Diễn tả mệnh lệnh/quy tắc/quy định chung, thường thấy trong văn bản, biển báo, nội quy', NULL, NULL, NULL, '{}', NULL, 65, 'Vる／Vない ＋ こと', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('4fef86d0-ef84-4c86-bc17-6a8104491f91', 'N2', 'Vる・Vない／Aい／Aな ＋ ことだ', '① Nên/Không nên... (lời khuyên)　② Vô cùng, rất~ (cảm thán)', NULL, NULL, NULL, NULL, NULL, NULL, '{}', NULL, 65, 'Vる・Vない／Aい／Aな ＋ ことだ', 'pdf', 'ok')
