insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('d9d4ec05-b9a5-4790-a704-a698de26675c', 'N2', 'Vない／Aいく／Aなで／Nで ＋ ないことは(も)ない', 'Không phải là không.../Có lẽ, có thể là... (phủ định kép, thừa nhận 1 phần)', NULL, 'Vない／Aいく／Aなで／Nで ＋ ないことは(も)ない', 'Phủ định kép để thừa nhận 1 phần khả năng/sự thật, dù không hoàn toàn khẳng định', NULL, NULL, NULL, '{}', NULL, 65, 'Vない／Aいく／Aなで／Nで ＋ ないことは(も)ない', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('ef089d16-d4c2-4ff3-a19e-52deb4eaf3e4', 'N2', 'V／Aい(普通形)／Aな／である／Nである ＋ ことだし', 'Vì, bởi vì...nên (nêu 1 trong nhiều lý do dẫn đến quyết định/đề nghị)', NULL, 'V／Aい(普通形)／Aな／である／Nである ＋ ことだし', 'Nêu 1 lý do (thường nhẹ nhàng, kèm theo đề nghị/quyết định) trong số nhiều lý do có thể có', NULL, NULL, NULL, '{}', NULL, 65, 'V／Aい(普通形)／Aな／である／Nである ＋ ことだし', 'pdf', 'ok')
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('a2897a3f-5054-49f0-895d-ba87892d7a16', '4fef86d0-ef84-4c86-bc17-6a8104491f91', 1, 'Nên/Không nên... (đưa ra lời khuyên cụ thể)', 'Vる・Vない ＋ ことだ', 'Đưa ra lời khuyên cụ thể nên/không nên làm gì để đạt được mục đích đã nêu', NULL, 65, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('0112757a-8fd9-44b9-833f-174fe63af296', '4fef86d0-ef84-4c86-bc17-6a8104491f91', 2, 'Vô cùng, rất~ (cảm thán, đi với tính từ)', 'Aい／Aな ＋ ことだ', 'Nhấn mạnh mức độ cảm thán trước 1 sự việc/tính chất nào đó', NULL, 65, 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('9fed5bd5-1f67-4d79-8d6d-e6859715cbe6', NULL, 1, 'standard', '弟は休むことなく必死に勉強をしていた。', 'Em trai tôi quyết tâm học mà không nghỉ ngơi gì cả.', '弟は休む＿＿＿必死に勉強をしていた。', 'ことなく', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('9fed5bd5-1f67-4d79-8d6d-e6859715cbe6', NULL, 2, 'daily', '彼は諦めることなく、最後まで努力し続けた。', 'Anh ấy đã không từ bỏ mà tiếp tục nỗ lực đến cùng.', '彼は諦める＿＿＿、最後まで努力し続けた。', 'ことなく', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('9fed5bd5-1f67-4d79-8d6d-e6859715cbe6', NULL, 3, 'daily', '彼女は誰の助けも借りることなく、一人で問題を解決した。', 'Cô ấy đã tự mình giải quyết vấn đề mà không nhờ ai giúp đỡ.', '彼女は誰の助けも借りる＿＿＿、一人で問題を解決した。', 'ことなく', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('d29af820-f0d2-4519-a51c-dd2df2123769', NULL, 1, 'standard', '困ったことに、携帯の充電がなくなってしまい、連絡手段がなくなる。', 'Thật phiền khi sạc điện thoại bị hết, mất luôn cả phương tiện liên lạc.', '＿＿＿、携帯の充電がなくなってしまい、連絡手段がなくなる。', '困ったことに', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('d29af820-f0d2-4519-a51c-dd2df2123769', NULL, 2, 'daily', '嬉しいことに、試験に合格することができた。', 'Thật vui khi tôi đã có thể đỗ kỳ thi.', '＿＿＿、試験に合格することができた。', '嬉しいことに', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('d29af820-f0d2-4519-a51c-dd2df2123769', NULL, 3, 'daily', '残念なことに、旅行は中止になってしまった。', 'Thật đáng tiếc khi chuyến du lịch đã bị hủy.', '＿＿＿、旅行は中止になってしまった。', '残念なことに', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('fcbcd923-35a1-44e9-b7e0-c47640e43c4c', NULL, 1, 'standard', '日本に興味を持ったことから、日本に留学することを決意した。', 'Vì có hứng thú với Nhật Bản, tôi đã quyết định đi du học Nhật.', '日本に興味を持った＿＿＿、日本に留学することを決意した。', 'ことから', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('fcbcd923-35a1-44e9-b7e0-c47640e43c4c', NULL, 2, 'daily', '二人は同じ趣味を持っていたことから、仲良くなった。', 'Vì cả hai có cùng sở thích nên đã trở nên thân thiết.', '二人は同じ趣味を持っていた＿＿＿、仲良くなった。', 'ことから', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('fcbcd923-35a1-44e9-b7e0-c47640e43c4c', NULL, 3, 'daily', '事故が多いことから、この道路は危険だと言われている。', 'Vì có nhiều tai nạn nên con đường này được cho là nguy hiểm.', '事故が多い＿＿＿、この道路は危険だと言われている。', 'ことから', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('3b4f8ff8-1184-4d94-a0f8-76e866fc3d38', NULL, 1, 'standard', '彼女のことだから、すぐに友達ができるだろう。', 'Chính vì là cô ấy, nên chắc chắn sẽ có bạn mới ngay thôi.', '彼女の＿＿＿、すぐに友達ができるだろう。', 'ことだから', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('3b4f8ff8-1184-4d94-a0f8-76e866fc3d38', NULL, 2, 'daily', '真面目な彼のことだから、約束は必ず守るだろう。', 'Chính vì là anh ấy, một người nghiêm túc, nên chắc chắn sẽ giữ đúng lời hứa.', '真面目な彼の＿＿＿、約束は必ず守るだろう。', 'ことだから', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('3b4f8ff8-1184-4d94-a0f8-76e866fc3d38', NULL, 3, 'daily', '忙しい田中さんのことだから、返事が遅れるかもしれない。', 'Chính vì là anh Tanaka, người luôn bận rộn, nên có lẽ sẽ trả lời trễ.', '忙しい田中さんの＿＿＿、返事が遅れるかもしれない。', 'ことだから', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('76c6fc02-c3de-4df4-84e9-f56e2fcf285d', NULL, 1, 'standard', '実際に見てみないことには、判断することはできない。', 'Nếu không xem trực tiếp thì không thể suy đoán được.', '実際に見てみない＿＿＿、判断することはできない。', 'ことには', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('76c6fc02-c3de-4df4-84e9-f56e2fcf285d', NULL, 2, 'daily', 'やってみないことには、成功するかどうか分からない。', 'Nếu không thử làm thì sẽ không biết có thành công hay không.', 'やってみない＿＿＿、成功するかどうか分からない。', 'ことには', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('76c6fc02-c3de-4df4-84e9-f56e2fcf285d', NULL, 3, 'daily', '本人に確認しないことには、はっきりしたことは言えない。', 'Nếu không xác nhận với người đó thì không thể nói chắc chắn được.', '本人に確認しない＿＿＿、はっきりしたことは言えない。', 'ことには', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('fc69ea16-25fd-4255-a59a-d28a94132cba', NULL, 1, 'standard', '安全に運転するから、心配することはない。', 'Tôi lái xe an toàn nên không cần lo lắng đâu.', '安全に運転するから、心配する＿＿＿。', 'ことはない', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('fc69ea16-25fd-4255-a59a-d28a94132cba', NULL, 2, 'daily', 'そんなに謝ることはないですよ。', 'Bạn không cần phải xin lỗi nhiều như vậy đâu.', 'そんなに謝る＿＿＿ですよ。', 'ことはない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('fc69ea16-25fd-4255-a59a-d28a94132cba', NULL, 3, 'daily', '一人で悩むことはない、いつでも相談してください。', 'Bạn không cần phải một mình lo lắng, lúc nào cũng có thể tâm sự với tôi.', '一人で悩む＿＿＿、いつでも相談してください。', 'ことはない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('995943ee-3c92-40c0-8db3-119e36b765f6', NULL, 1, 'standard', '目上の人には常に敬意を持って接すること。', 'Hãy luôn giữ lòng kính trọng khi tiếp xúc với người bề trên.', '目上の人には常に敬意を持って接する＿＿＿。', 'こと', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('995943ee-3c92-40c0-8db3-119e36b765f6', NULL, 2, 'daily', '提出書類には必ず日付を記入すること。', 'Hãy nhớ điền ngày tháng vào giấy tờ nộp.', '提出書類には必ず日付を記入する＿＿＿。', 'こと', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('995943ee-3c92-40c0-8db3-119e36b765f6', NULL, 3, 'daily', '授業中は携帯電話を使用しないこと。', 'Không được sử dụng điện thoại di động trong giờ học.', '授業中は携帯電話を使用しない＿＿＿。', 'こと', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4fef86d0-ef84-4c86-bc17-6a8104491f91', 'a2897a3f-5054-49f0-895d-ba87892d7a16', 1, 'standard', '身体の健康を気遣うのであれば、野菜を食べることだ。', 'Nếu bạn để ý đến sức khỏe nên ăn rau.', '身体の健康を気遣うのであれば、野菜を食べる＿＿＿。', 'ことだ', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4fef86d0-ef84-4c86-bc17-6a8104491f91', 'a2897a3f-5054-49f0-895d-ba87892d7a16', 2, 'daily', '早く上手になりたいなら、毎日練習することだ。', 'Nếu muốn giỏi nhanh thì nên luyện tập mỗi ngày.', '早く上手になりたいなら、毎日練習する＿＿＿。', 'ことだ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4fef86d0-ef84-4c86-bc17-6a8104491f91', 'a2897a3f-5054-49f0-895d-ba87892d7a16', 3, 'daily', '風邪を治したいなら、しっかり休むことだ。', 'Nếu muốn khỏi cảm thì nên nghỉ ngơi đầy đủ.', '風邪を治したいなら、しっかり休む＿＿＿。', 'ことだ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4fef86d0-ef84-4c86-bc17-6a8104491f91', '0112757a-8fd9-44b9-833f-174fe63af296', 1, 'standard', '屋根から落ちるなんて大変なことだ。', 'Việc bị rơi từ trên mái nhà xuống thật là nguy hiểm.', '屋根から落ちるなんて大変な＿＿＿。', 'ことだ', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4fef86d0-ef84-4c86-bc17-6a8104491f91', '0112757a-8fd9-44b9-833f-174fe63af296', 2, 'daily', '一人で全部やり遂げるなんて立派なことだ。', 'Một mình làm xong hết mọi việc thật là đáng khen.', '一人で全部やり遂げるなんて立派な＿＿＿。', 'ことだ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4fef86d0-ef84-4c86-bc17-6a8104491f91', '0112757a-8fd9-44b9-833f-174fe63af296', 3, 'daily', '毎日残業するなんて大変なことだ。', 'Ngày nào cũng làm thêm giờ thật là vất vả.', '毎日残業するなんて大変な＿＿＿。', 'ことだ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f1a99da7-cebd-40f9-bd76-57a017815de6', NULL, 1, 'standard', '彼の行動によって、どれだけの命が救われたことか。', 'Nhờ vào hành động của anh ấy mà biết bao sinh mệnh được cứu.', '彼の行動によって、どれだけの命が救われた＿＿＿。', 'ことか', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f1a99da7-cebd-40f9-bd76-57a017815de6', NULL, 2, 'daily', '子供の笑顔を見るたびに、どれほど癒されることか。', 'Mỗi khi nhìn thấy nụ cười của con, tôi được chữa lành biết bao nhiêu.', '子供の笑顔を見るたびに、どれほど癒される＿＿＿。', 'ことか', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f1a99da7-cebd-40f9-bd76-57a017815de6', NULL, 3, 'daily', 'あの時どれだけ心配したことか。', 'Lúc đó tôi đã lo lắng biết bao nhiêu.', 'あの時どれだけ心配した＿＿＿。', 'ことか', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('d9d4ec05-b9a5-4790-a704-a698de26675c', NULL, 1, 'standard', 'それは私のせいでないことはないけど、上司に言われてやっただけだ。', 'Việc đó có lẽ cũng có lỗi của tôi, nhưng thực ra tôi chỉ làm theo lời sếp thôi.', 'それは私のせいで＿＿＿けど、上司に言われてやっただけだ。', 'ないことはない', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('d9d4ec05-b9a5-4790-a704-a698de26675c', NULL, 2, 'daily', '忙しくて行けないことはないが、あまり気が進まない。', 'Không phải là không đi được vì bận, nhưng tôi không hào hứng lắm.', '忙しくて行け＿＿＿が、あまり気が進まない。', 'ないことはない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('d9d4ec05-b9a5-4790-a704-a698de26675c', NULL, 3, 'daily', '高いから買えないことはないが、もったいない気がする。', 'Không phải là không mua được vì đắt, nhưng tôi cảm thấy phí tiền.', '高いから買え＿＿＿が、もったいない気がする。', 'ないことはない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ef089d16-d4c2-4ff3-a19e-52deb4eaf3e4', NULL, 1, 'standard', '仕事も済んだことだし、一杯飲みにいこうよ。', 'Vì công việc cũng đã hoàn thành rồi, cùng đi uống bia nào.', '仕事も済んだ＿＿＿、一杯飲みにいこうよ。', 'ことだし', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ef089d16-d4c2-4ff3-a19e-52deb4eaf3e4', NULL, 2, 'daily', '天気もいいことだし、散歩にでも行きましょう。', 'Vì thời tiết cũng đẹp nên chúng ta đi dạo đi.', '天気もいい＿＿＿、散歩にでも行きましょう。', 'ことだし', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ef089d16-d4c2-4ff3-a19e-52deb4eaf3e4', NULL, 3, 'daily', 'もう遅いことだし、そろそろ帰りましょう。', 'Vì cũng đã muộn rồi nên chúng ta về thôi.', 'もう遅い＿＿＿、そろそろ帰りましょう。', 'ことだし', 'generated');
